const fs=require('fs'),vm=require('vm');class QueryDate extends Date{constructor(...args){super(...(args.length?args:['2026-11-24T12:00:00Z']));}}
async function setup(){const c={Intl,Date:QueryDate,URLSearchParams,document:{addEventListener(){},getElementById(){return null}},location:{search:''}};c.window=c;vm.createContext(c);for(const f of ['annual-analytics.js','dashboard-context.js'])vm.runInContext(fs.readFileSync(require('path').join(__dirname,'../..',f),'utf8'),c);
const invoice=(id,pos_id,status,amount,extra={})=>({id,pos_id,po_no:'P'+pos_id,project_id:pos_id,project_name:pos_id===1?'Alpha':'Beta',invoice_no:'I'+id,status,invoice_amount:amount,approval_date:'2026-01-01',start_date:'2026-01-01',payment_terms:30,...extra});
const records={projects:[{id:1,project_name:'Alpha',company:'Customer A',department:'D1'},{id:2,project_name:'Beta',company:'Customer B',department:'D2'}],pos:[{id:1,po_no:'P1',project_id:1,project_name:'Alpha',company:'Customer A',department:'D1',vat:true,po_value_ex_vat:100,po_date:'2026-01-01'},{id:2,po_no:'P2',project_id:2,project_name:'Beta',company:'Customer B',department:'D2',vat:false,po_value_ex_vat:400,po_date:'2026-01-01'}],invoices:[invoice(1,1,'Approved',100,{paid_amount:20,retention_amount:10,retention_vat:1.5}),invoice(2,1,'Completed',200,{paid_amount:230}),invoice(3,1,'Waiting For approval',300,{approval_date:null}),invoice(4,1,'Draft',400,{approval_date:null}),invoice(5,2,'Approved',500,{paid_amount:100}),invoice(6,1,'Canceled',100),invoice(7,1,'Draft',20,{approval_date:null,start_date:'2027-01-01'})],invoice_collections:[{id:1,invoice_id:1,collection_date:'2026-01-15',amount:10},{id:2,invoice_id:1,collection_date:'2025-12-15',amount:10},{id:3,invoice_id:2,collection_date:'2026-01-15',amount:230},{id:4,invoice_id:5,collection_date:'2026-01-15',amount:100}],po_advance_payments:[{id:1,po_id:1,payment_date:'2026-01-15',amount:50},{id:2,po_id:2,payment_date:'2026-01-15',amount:70}]};
await c.PEAnnual.load({from:t=>({select:()=>({order:()=>({range:async(from,to)=>({data:records[t].slice(from,to+1)})})})})});
return {c,records};}
module.exports={setup};

